    public static void checkPrecisionAccuracy(BaseExchange exchange, Object skippedProperties, Object method, Object entry, Object key)
    {
        if (Helpers.inOp(skippedProperties, key))
        {
            return;
        }
        if (Helpers.isTrue(exchange.isTickPrecision()))
        {
            // TICK_SIZE should be above zero
            AssertGreater(exchange, skippedProperties, method, entry, key, "0");
            // the below array of integers are inexistent tick-sizes (theoretically technically possible, but not in real-world cases), so in our case, such values probably indicate an incorrectly implemented tick-sizes calculation, so we throw new RuntimeException(e)rror
            List<Object> decimalNumbers = new ArrayList<Object>(Arrays.asList("2", "3", "4", "5", "6", "7", "8", "9", "11", "12", "13", "14", "15", "16"));
            if (java.util.Objects.equals(key, "amount") && Helpers.inOp(skippedProperties, "precisionAmountAbnormal"))
            {
                return;
            }
            for (var i = 0; i < ((List<?>)decimalNumbers).size(); i++)
            {
                String num = (String) Helpers.GetValue(decimalNumbers, i);
                String numStr = num;
                AssertNonEqual(exchange, skippedProperties, method, entry, key, numStr);
            }
        } else
        {
            // todo: significant-digits return doubles from `this.parseNumber`, so for now can't Assert against integer atm
            // AssertInteger (exchange, skippedProperties, method, entry, key); // should be integer
            AssertLessOrEqual(exchange, skippedProperties, method, entry, key, "18"); // should be under 18 decimals
            AssertGreaterOrEqual(exchange, skippedProperties, method, entry, key, "-8"); // in real-world cases, there would not be less than that
        }
    }
    public static CompletableFuture<Object> fetchBestBidAsk(BaseExchange exchange, Object method, Object symbol)
    {

        return BaseExchange.supplyAsync(() -> {

        Object logText = logTemplate(exchange, method, new HashMap<String, Object>() {{}});
        // find out best bid/ask price
        Object bestBid = null;
        Object bestAsk = null;
        String usedMethod = null;
        if ((!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchOrderBook"), null)) && (!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchOrderBook"), false)))
        {
            usedMethod = "fetchOrderBook";
            Object orderbook = ((CompletableFuture<Object>)Helpers.callDynamically(exchange, "fetchOrderBook", new Object[]{symbol})).join();
            Object bids = exchange.safeList(orderbook, "bids");
            Object asks = exchange.safeList(orderbook, "asks");
            Object bestBidArray = exchange.safeList(bids, 0);
            Object bestAskArray = exchange.safeList(asks, 0);
            bestBid = exchange.safeNumber(bestBidArray, 0);
            bestAsk = exchange.safeNumber(bestAskArray, 0);
        } else if ((!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchBidsAsks"), null)) && (!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchBidsAsks"), false)))
        {
            usedMethod = "fetchBidsAsks";
            Object tickers = ((CompletableFuture<Object>)Helpers.callDynamically(exchange, "fetchBidsAsks", new Object[]{new ArrayList<Object>(Arrays.asList(symbol))})).join();
            Object ticker = exchange.safeDict(tickers, symbol);
            bestBid = exchange.safeNumber(ticker, "bid");
            bestAsk = exchange.safeNumber(ticker, "ask");
        } else if ((!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchTicker"), null)) && (!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchTicker"), false)))
        {
            usedMethod = "fetchTicker";
            Object ticker = ((CompletableFuture<Object>)Helpers.callDynamically(exchange, "fetchTicker", new Object[]{symbol})).join();
            bestBid = exchange.safeNumber(ticker, "bid");
            bestAsk = exchange.safeNumber(ticker, "ask");
        } else if ((!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchTickers"), null)) && (!java.util.Objects.equals(Helpers.GetValue(exchange.has, "fetchTickers"), false)))
        {
            usedMethod = "fetchTickers";
            Object tickers = ((CompletableFuture<Object>)Helpers.callDynamically(exchange, "fetchTickers", new Object[]{new ArrayList<Object>(Arrays.asList(symbol))})).join();
            Object ticker = exchange.safeDict(tickers, symbol);
            bestBid = exchange.safeNumber(ticker, "bid");
            bestAsk = exchange.safeNumber(ticker, "ask");
        }
        //
        Assert(!java.util.Objects.equals(bestBid, null) && !java.util.Objects.equals(bestAsk, null), ((Helpers.add((((Helpers.add((logText + " "), exchange.id) + " could not get best bid/ask for ") + symbol) + " using "), usedMethod) + " while testing ") + method));
        return new ArrayList<Object>(Arrays.asList(bestBid, bestAsk));
        });

    }
    public static CompletableFuture<Object> fetchOrder(BaseExchange exchange, Object symbol, Object orderId, Object skippedProperties)
    {

        return BaseExchange.supplyAsync(() -> {

        Object fetchedOrder = null;
        Object originalId = orderId;
        // set 'since' to 5 minute ago for optimal results
        Object sinceTime = Helpers.subtract(exchange.milliseconds(), ((1000L * 60L) * 5L));
        // iterate
        List<Object> methods_singular = new ArrayList<Object>(Arrays.asList("fetchOrder", "fetchOpenOrder", "fetchClosedOrder", "fetchCanceledOrder"));
        for (var i = 0; i < ((List<?>)methods_singular).size(); i++)
        {
            String singularFetchName = (String) Helpers.GetValue(methods_singular, i);
            if ((!java.util.Objects.equals(Helpers.GetValue(exchange.has, singularFetchName), null)) && (!java.util.Objects.equals(Helpers.GetValue(exchange.has, singularFetchName), false)))
            {
                Object currentOrder = ((CompletableFuture<Object>)Helpers.callDynamically(exchange, singularFetchName, new Object[] { originalId, symbol })).join();
                // if there is an id inside the order, it means the order was fetched successfully
                if (java.util.Objects.equals(Helpers.GetValue(currentOrder, "id"), originalId))
                {
                    fetchedOrder = currentOrder;
                    break;
                }
            }
        }
        //
        // search through plural methods
        if (java.util.Objects.equals(fetchedOrder, null))
        {
            List<Object> methods_plural = new ArrayList<Object>(Arrays.asList("fetchOrders", "fetchOpenOrders", "fetchClosedOrders", "fetchCanceledOrders"));
            for (var i = 0; i < ((List<?>)methods_plural).size(); i++)
            {
                String pluralFetchName = (String) Helpers.GetValue(methods_plural, i);
                if ((!java.util.Objects.equals(Helpers.GetValue(exchange.has, pluralFetchName), null)) && (!java.util.Objects.equals(Helpers.GetValue(exchange.has, pluralFetchName), false)))
                {
                    Object orders = ((CompletableFuture<Object>)Helpers.callDynamically(exchange, pluralFetchName, new Object[] { symbol, sinceTime })).join();
                    Boolean found = false;
                    for (var j = 0; Helpers.isLessThan(j, Helpers.getArrayLength(orders)); j++)
                    {
                        Object currentOrder = Helpers.GetValue(orders, j);
                        if (java.util.Objects.equals(Helpers.GetValue(currentOrder, "id"), originalId))
                        {
                            fetchedOrder = currentOrder;
                            found = true;
                            break;
                        }
                    }
                    if (Helpers.isTrue(found))
                    {
                        break;
                    }
                }
            }
        }
        return fetchedOrder;
        });

    }
    public static void AssertOrderState(BaseExchange exchange, Object skippedProperties, Object method, Object order, Object AssertedStatus, Object strictCheck)
    {
        // note, `strictCheck` is `true` only from "fetchOrder" cases
        Object logText = logTemplate(exchange, method, order);
        Object msg = ((("order should be " + AssertedStatus) + ", but it was not Asserted") + logText);
        String filled = exchange.safeString(order, "filled");
        String amount = exchange.safeString(order, "amount");
        // shorthand variables
        Boolean statusUndefined = (java.util.Objects.equals(Helpers.GetValue(order, "status"), null));
        Boolean statusOpen = (java.util.Objects.equals(Helpers.GetValue(order, "status"), "open"));
        Boolean statusClosed = (java.util.Objects.equals(Helpers.GetValue(order, "status"), "closed"));
        Boolean statusClanceled = (java.util.Objects.equals(Helpers.GetValue(order, "status"), "canceled"));
        Boolean filledDefined = (!java.util.Objects.equals(filled, null));
        Boolean amountDefined = (!java.util.Objects.equals(amount, null));
        Object condition = null;
        //
        // ### OPEN STATUS
        //
        // if strict check, then 'status' must be 'open' and filled amount should be less then whole order amount
        Object strictOpen = Helpers.isTrue(statusOpen) && (Helpers.isTrue(filledDefined) && Helpers.isTrue(amountDefined) && Helpers.isLessThan(filled, amount));
        // if non-strict check, then accept & ignore undefined values
        Object nonstrictOpen = (Helpers.isTrue(statusOpen) || Helpers.isTrue(statusUndefined)) && ((!Helpers.isTrue(filledDefined) || !Helpers.isTrue(amountDefined)) || Helpers.isTrue(Precise.stringLt(filled, amount)));
        // check
        if (java.util.Objects.equals(AssertedStatus, "open"))
        {
            condition = ((Helpers.isTrue(strictCheck))) ? strictOpen : nonstrictOpen;
            Assert(condition, msg);
            return;
        }
        //
        // ### CLOSED STATUS
        //
        // if strict check, then 'status' must be 'closed' and filled amount should be equal to the whole order amount
        Object closedStrict = Helpers.isTrue(statusClosed) && (Helpers.isTrue(filledDefined) && Helpers.isTrue(amountDefined) && Helpers.isTrue(Precise.stringEq(filled, amount)));
        // if non-strict check, then accept & ignore undefined values
        Object closedNonStrict = (Helpers.isTrue(statusClosed) || Helpers.isTrue(statusUndefined)) && ((!Helpers.isTrue(filledDefined) || !Helpers.isTrue(amountDefined)) || Helpers.isTrue(Precise.stringEq(filled, amount)));
        // check
        if (java.util.Objects.equals(AssertedStatus, "closed"))
        {
            condition = ((Helpers.isTrue(strictCheck))) ? closedStrict : closedNonStrict;
            Assert(condition, msg);
            return;
        }
        //
        // ### CANCELED STATUS
        //
        // if strict check, then 'status' must be 'canceled' and filled amount should be less then whole order amount
        Object canceledStrict = Helpers.isTrue(statusClanceled) && (Helpers.isTrue(filledDefined) && Helpers.isTrue(amountDefined) && Helpers.isTrue(Precise.stringLt(filled, amount)));
        // if non-strict check, then accept & ignore undefined values
        Object canceledNonStrict = (Helpers.isTrue(statusClanceled) || Helpers.isTrue(statusUndefined)) && ((!Helpers.isTrue(filledDefined) || !Helpers.isTrue(amountDefined)) || Helpers.isTrue(Precise.stringLt(filled, amount)));
        // check
        if (java.util.Objects.equals(AssertedStatus, "canceled"))
        {
            condition = ((Helpers.isTrue(strictCheck))) ? canceledStrict : canceledNonStrict;
            Assert(condition, msg);
            return;
        }
        //
        // ### CLOSED_or_CANCELED STATUS
        //
        if (java.util.Objects.equals(AssertedStatus, "closed_or_canceled"))
        {
            condition = ((Helpers.isTrue(strictCheck))) ? (Helpers.isTrue(closedStrict) || Helpers.isTrue(canceledStrict)) : (Helpers.isTrue(closedNonStrict) || Helpers.isTrue(canceledNonStrict));
            Assert(condition, msg);
            return;
        }
    }
    public static Object getActiveMarkets(BaseExchange exchange, Object... optionalArgs)
    {
        Object includeUnknown = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : true;
        Object filteredActive = exchange.filterBy(exchange.markets, "active", true);
        if (Helpers.isTrue(includeUnknown))
        {
            Object filteredUndefined = exchange.filterBy(exchange.markets, "active", null);
            return exchange.arrayConcat(filteredActive, filteredUndefined);
        }
        return filteredActive;
    }
