    public static Object concat(Object... optionalArgs)
    {
        // we use this method temporarily, because of ast-transpiler issue across langs
        Object a = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : null;
        Object b = optionalArgs != null && optionalArgs.length > 1 ? optionalArgs[1] : null;
        if (java.util.Objects.equals(a, null))
        {
            return b;
        } else if (java.util.Objects.equals(b, null))
        {
            return a;
        } else
        {
            List<Object> result = new ArrayList<Object>(Arrays.asList());
            for (var i = 0; i < ((List<?>)a).size(); i++)
            {
                ((List<Object>)result).add(Helpers.GetValue(a, i));
            }
            for (var j = 0; j < ((List<?>)b).size(); j++)
            {
                ((List<Object>)result).add(Helpers.GetValue(b, j));
            }
            return result;
        }
    }
    public static void AssertDictionaryResponse(BaseExchange exchange, Object method, Object response, Object... optionalArgs)
    {
        // php cannot distinguish an empty dict from an empty list, both are a plain array
        // there, so an empty array response is shape indeterminate and accepted, observed
        // as false positive FAILs in the live tests on https://github.com/ccxt/ccxt/pull/29696
        Object hint = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : null;
        Boolean isEmptyArrayResponse = false;
        if (Helpers.isTrue((response instanceof List)))
        {
            Object responseLength = ((List<?>)response).size();
            isEmptyArrayResponse = (Helpers.isEqual(responseLength, 0));
        }
        String hintText = "";
        if (!java.util.Objects.equals(hint, null))
        {
            hintText = (" " + hint);
        }
        Assert(Helpers.isTrue(exchange.isDictionary(response)) || Helpers.isTrue(isEmptyArrayResponse), (((((exchange.id + " ") + method) + hintText) + " must return a dict. ") + exchange.json(response)));
    }
